window.kbPageData["views/entry/k-507146993bee78cc"] = {"key":"entry/k-507146993bee78cc","state":{"route":"entry/k-507146993bee78cc"},"node":{"id":"k-507146993bee78cc","mode":"k","title":"两集合的交集人数","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["集合人数等于仅属于该集合的人数加上两集合的交集人数"],"qs":["江苏 2024 C类 行测#64"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两个集合的交集包含同时属于两个集合的成员。任一集合的人数等于仅属于该集合的人数与交集人数之和。","review":{"definition":"两个集合的交集包含同时属于两个集合的成员。任一集合的人数等于仅属于该集合的人数与交集人数之和。","explanation":"180名会员中，参加甲活动的有108人，其中80人只参加甲活动，因此两项都参加的有28人。这28人也计入参加乙活动的90人，从90人中扣除他们，得到只参加乙活动的有62人，选C。","references":[],"evidence":"甲、乙两项活动都参加的会员人数为108-80=28人","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#64":{"paper":"江苏 2024 C类 行测","n":64,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",11],"asrc":["02d6b49839583bdaf297.pdf",18],"card":"56ff358139b5a56940b95a72","links":[{"id":"k-507146993bee78cc","role":"解题依据","why":"每项活动的总人数都包含同一个交集，可由甲活动总人数和仅参加甲的人数确定该交集。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-507146993bee78cc":[["江苏 2024 C类 行测#64"]]}};
